const STORE='asset360-ew-v2';
const LEGACY_STORE='asset360-ew-v1';
const MONTHS=Array.from({length:12},(_,i)=>{const d=new Date(2025,10+i,1);return d.toISOString().slice(0,7)});
const CATS=[{id:'commercial',name:'Commercial & STR',short:'Commercial',weight:1.3},{id:'demand',name:'Demand & forward pace',short:'Demand & pace',weight:1.2},{id:'labor',name:'Labor & operations',short:'Operations',weight:1.2},{id:'guest',name:'Guest experience',short:'Guest',weight:1.2},{id:'finance',name:'Financial & liquidity',short:'Financial',weight:1.1},{id:'supply',name:'Supply & market threats',short:'Supply',weight:1},{id:'asset',name:'Physical asset & QA',short:'Asset care',weight:1},{id:'capital',name:'Capital structure & lifecycle',short:'Capital',weight:1.25}];
